#!/usr/bin/env python3
# tools/titan/results/wave55-plan/plan-prose.py — keeps PLAN.md's numbers equal to the GENERATED files (wave-54 lesson 11:
# "a commit that regenerates expectations.json restates every prose number it changes in the same commit, or the prose
# cites the generated file instead of carrying numbers").
#
# Why a script: wave 54's PLAN.md went stale the moment a hand-off regenerated expectations.json (iOS carriers 27 vs 24,
# 19 revert units vs 18, four DEGENERATE vs 8 — S1 should-fix 7) and only the machine-read file was right. Here every
# number PLAN.md takes from a generated file sits inside a marked block
#     <!-- gen:NAME (plan-prose.py; do not edit by hand) --> … <!-- /gen:NAME -->
# that this script renders from expectations.json / plan-build.out.txt / cells-wave54-final.json, so a regeneration is
# followed by `--fill` (the restatement, in the same commit) and `--check` turns red until it is.
#
# What --check asserts (exit 1 on any violation, every violation printed):
#   1. every gen block equals its fresh rendering, and every renderer's block is present exactly once;
#   2. §9 has a table row "| <id> |" for every expectations.json planDecisions id (C1–C15, D1–D7);
#   3. every hand-written cell citation "wave54-final <sec>/<test> <web|ios|android> <P|f> <ssim>" outside the gen
#      blocks equals cells-wave54-final.json (the scorer's own loadRun, written by snapshot-cells.mjs);
#   4. the ```landing-order``` block of §4 — rendered from land-units.sh's GENERATED landing-manifest.json, so this is an
#      independent re-check of the landing stage's order against plan-build.py's JSON — lists every revert unit of every
#      lane exactly once (a contingency is a `--` line until it lands), and
#      the order honours: each lane's revertOrder (a unit that must be reverted BEFORE X lands AFTER X); L7's
#      landingOrder; C10 (every L4 unit before every L3 unit before every L5 unit: SeamReachabilityTest gains one module
#      line per seam-only module, landing L4 → L3 → L5); L1 NB-ios before L5 U3-ios (seam 6 is re-anchored by content
#      after L1's seam 1 moves PlaceholderLabel's lines); L5 D after L5 U2o-ios and U2o-android (C7: the
#      counter-style-table.mjs SUFFIX NOTE is true only once the U+3001 stand-in gap is gone);
#   5. every lane has its "### L<n> · <name>" heading;
#   6. every landing-manifest.json unit is a revert (or contingency) unit of expectations.json with the SAME revertOrder;
#   7. (plan-skeptic round 1, process-holes S7) no REGENERABLE count is hand-typed outside the gen blocks: a phrase of the
#      STRAY list below with a number in it ("28 revert units", "41 of the 43", "L6: 7 —", "[X] ×6", "the 10 controls", …)
#      is an error — the number goes in a gen block or the prose cites the generated file (wave-54 lesson 11; E10: after a
#      regeneration with L6 U2 reverted, the tally block said 6 withdrawn while the hand list still said "L6: 7").
# Pure JSON / text: no image is decoded, no run directory is read, nothing is built or executed.
#
# Usage (from anywhere; paths are resolved beside this file):
#   /opt/homebrew/bin/python3.12 -B tools/titan/results/wave55-plan/plan-prose.py --fill  [PLAN.md]
#   /opt/homebrew/bin/python3.12 -B tools/titan/results/wave55-plan/plan-prose.py --check [PLAN.md]
#   … --render NAME                    print one block (debug)
#   … --exp FILE / --cells FILE / --report FILE   read another expectations.json / cells snapshot / plan-build report
#                                       (the mutation proofs in plan-prose.out.txt use these on scratch copies)
import hashlib, json, os, re, sys

HERE = os.path.dirname(os.path.abspath(__file__))
args = sys.argv[1:]
def opt(name, default=None):
    """Pop `--name value` from args."""
    if name in args:
        i = args.index(name); val = args[i + 1]; del args[i:i + 2]; return val
    return default
EXP_PATH = opt('--exp', os.path.join(HERE, 'expectations.json'))
CELLS_PATH = opt('--cells', os.path.join(HERE, 'cells-wave54-final.json'))
REPORT_PATH = opt('--report', os.path.join(HERE, 'plan-build.out.txt'))
LANDING_PATH = opt('--landing', os.path.join(HERE, 'landing-manifest.json'))   # GENERATED by land-units.sh --emit-manifest
RENDER = opt('--render')
MODE = '--fill' if '--fill' in args else ('--check' if '--check' in args else None)
for f in ('--fill', '--check'):
    if f in args: args.remove(f)
PLAN = os.path.abspath(args[0]) if args else os.path.join(HERE, 'PLAN.md')

EXP = json.load(open(EXP_PATH))
EXP_SHA = hashlib.sha256(open(EXP_PATH, 'rb').read()).hexdigest()
LANDING = json.load(open(LANDING_PATH))
LANDING_SHA = hashlib.sha256(open(LANDING_PATH, 'rb').read()).hexdigest()
CELLS = json.load(open(CELLS_PATH))
REPORT = open(REPORT_PATH).read()
PLATS = ('web', 'ios', 'android')
LANES = EXP['lanes']
SHORT = {lid.split('-', 1)[0]: lid for lid in LANES}          # 'L1' → 'L1-hyphen-ios-linebox'

def esc(s):
    """A string inside a markdown table cell: GFM needs every '|' escaped (also inside code spans) and no newline."""
    return str(s).replace('|', '\\|').replace('\n', ' ')

def code(s):
    """Inline code for a verbatim string; a backtick inside it widens the fence."""
    s = str(s)
    return f'`` {s} ``' if '`' in s else f'`{s}`'

# ── global blocks ──────────────────────────────────────────────────────────────────────────────────────────────────────
def r_header():
    t = CELLS['totals']
    tot = ' · '.join(f"{p} {t[p][0]}/{t[p][1]}" for p in PLATS)
    return '\n'.join([
        f"- Run of record **`{CELLS['run']}`**: {tot}, {len(CELLS['cells'])} scored cells (`cells-wave54-final.json` `totals`, "
        "written by `snapshot-cells.mjs` with the scorer's own `loadRun`).",
        f"- `expectations.json` sha256 `{EXP_SHA}`: readAgainst `{EXP['readAgainst']}`, base `{EXP['base']}`, "
        f"interpreter {code(EXP['interpreter'])}.",
        f"- Opening gate (`expectations.json` `openingGate.recorded`): {EXP['openingGate']['recorded']}",
    ])

def r_report():
    """plan-build.out.txt verbatim: the generator's own count of everything PLAN.md would otherwise retype."""
    return '```text\n' + REPORT.rstrip('\n') + '\n```'

def flip_tiers():
    """The generator's tiering, verbatim (plan-build.py: f→P rows only; DEGENERATE ones included — the scorer counts them)."""
    flips = {p: {'HIGH/MED-HIGH': [], 'MED/MED-LOW': [], 'LOW': []} for p in PLATS}
    for l in LANES.values():
        for p in l['predictions']:
            if p['kind'] == 'non-corpus' or not p['from'].startswith('f') or not p['to'].startswith('P'):
                continue
            plat = p['cell'].rsplit(' ', 1)[1]; c = p['confidence']
            tier = 'HIGH/MED-HIGH' if c.startswith(('HIGH', 'MED-HIGH')) else ('MED/MED-LOW' if c.startswith('MED') else 'LOW')
            flips[plat][tier].append(p['cell'].rsplit(' ', 1)[0].replace('.html', ''))
    return flips

def r_movement():
    t = CELLS['totals']; f = flip_tiers()
    dbc = set(EXP['degenerateByConstruction'])
    stay = {' '.join(e.split(' ')[:2]) for e in EXP['stayDegenerateEvenIfPass']}      # "<sec>/<test>.html <platform>"
    lines = ['| platform | wave55-open (= wave54-final) | HIGH / MED-HIGH flips | line | MED / MED-LOW flips | ceiling (the scorer\'s count) | '
             'flips on `stayDegenerateEvenIfPass` (never claimed) | flips in `degenerateByConstruction` (a gain only when retired) | LOW (never counted) |',
             '|---|---|---|---|---|---|---|---|---|']
    for p in PLATS:
        hi, med, low = f[p]['HIGH/MED-HIGH'], f[p]['MED/MED-LOW'], f[p]['LOW']
        never = [c for c in hi + med if f'{c}.html {p}' in stay]
        dbcl = [c for c in hi + med if c + '.html' in dbc]
        lines.append(f"| {p} | {t[p][0]}/{t[p][1]} | +{len(hi)} {esc(', '.join(hi)) or '—'} | **{t[p][0] + len(hi)}** | "
                     f"+{len(med)} {esc(', '.join(med)) or '—'} | **{t[p][0] + len(hi) + len(med)}** | {len(never)} {esc(', '.join(never)) or ''} | "
                     f"{len(dbcl)} {esc(', '.join(dbcl)) or ''} | {len(low)} |")
    lines.append('')
    lines.append('Lost: ' + (', '.join(EXP['expected']['lost']) or '∅') + ' · unmeasured-now: ' +
                 (', '.join(EXP['expected']['unmeasuredNow']) or '∅') + ' · newly measured: ' +
                 (', '.join(EXP['expected']['newlyMeasured']) or '∅') + f" (`expectations.json` `expected`). Fixture net: {EXP['expected']['fixtureNet']}.")
    return '\n'.join(lines)

def r_tally():
    pc = EXP['pictureCorrectTally']; po = pc.get('paintOrderOnly', [])
    out = [f"Rule (`expectations.json` `pictureCorrectTally.rule`): {pc['rule']}", '',
           f"**{len(pc['full'])} in full · {len(pc['part'])} in part · {len(po)} paint order only (never counted) · {len(pc['withdrawn'])} withdrawn by probe decisions.**", '',
           '| # | cell | its key(s) (every one must print OK on the closing run) |', '|---|---|---|']
    for i, e in enumerate(pc['full'], 1):
        out.append(f"| {i} | {code(e['cell'])} | {esc('; '.join(e['keys']))} |")
    for e in pc['part']:
        out.append(f"| part | {code(e['cell'])} | {esc('; '.join(e['keys']))} |")
    for e in po:
        out.append(f"| paint order only | {code(e['cell'])} | {esc('; '.join(e['keys']))} |")
    for e in pc['withdrawn']:
        out.append(f"| withdrawn | {code(e.get('cell', e))} | {esc(json.dumps(e, ensure_ascii=False))} |")
    if po:
        out += ['', f"`paintOrderOnlyRule`: {pc.get('paintOrderOnlyRule', '')}"]
    return '\n'.join(out)

def lane_of_key(k):
    """The lane whose geometryProbes registers this '<script> <key>' tally key."""
    for lid, l in LANES.items():
        for pr in l['geometryProbes']:
            sc = os.path.basename(next(t for t in pr['cmd'].split() if t.endswith('.py')))
            if k.startswith(sc + ' ') and k[len(sc) + 1:] in pr['expect']:
                return lid
    return '?'

def r_tally_by_lane():
    """§1 "By lane": the tally entries grouped by the lane of their FIRST key (round 1, S7: was hand-typed and went stale)."""
    pc = EXP['pictureCorrectTally']
    out = ['| lane | in full | paint order only (never counted) | withdrawn by probe decisions | cells (in full) |', '|---|---|---|---|---|']
    for lid in LANES:
        f = [e for e in pc['full'] if lane_of_key(e['keys'][0]) == lid]
        po = [e for e in pc.get('paintOrderOnly', []) if lane_of_key(e['keys'][0]) == lid]
        wd = [e for e in pc['withdrawn'] if e.get('keys') and lane_of_key(e['keys'][0]) == lid]
        if f or po or wd:
            out.append(f"| {lid} | {len(f)} | {len(po)} | {len(wd)} | {esc(', '.join(code(e['cell']) for e in f)) or '—'} |")
    return '\n'.join(out)

def r_stage1_required():
    """§7 "What each lane must show at stage 1" (round 1, S7): per lane, the keys stage 1 reads (by class) and the keys first
    read at stage 2, counted from geometryProbes × stage1Probe.sections, and the stage1Decision verbatim (the record)."""
    s1 = set(EXP['stage1Probe']['sections'])
    out = ['| lane | stage-1 sections | gating keys read at stage 1 | report keys read at stage 1 | keys first read at stage 2 |', '|---|---|---|---|---|']
    dec = []
    for lid, l in LANES.items():
        g1, r1, s2 = [], [], []
        for pr in l['geometryProbes']:
            for k, c in pr['keyCells'].items():
                sec = c.split('/')[0]
                if sec not in s1:
                    s2.append(k)
                elif k in pr.get('gating', {}):
                    g1.append(k)
                elif k in pr.get('report', []):
                    r1.append(k)
        out.append(f"| {lid} | {', '.join(l.get('stage1Sections') or []) or '— (no device window)'} | {len(g1)}: {esc(', '.join(code(k) for k in g1)) or '—'} | "
                   f"{len(r1)}: {esc(', '.join(code(k) for k in r1)) or '—'} | {len(s2)}{(': ' + esc(', '.join(code(k) for k in s2[:8])) + (' …' if len(s2) > 8 else '')) if s2 else ''} |")
        dec.append(f"- **{lid}** `stage1Decision`: {l['stage1Decision']}")
    return '\n'.join(out + [''] + dec)

def r_degenerate():
    out = [f"**`stayDegenerateEvenIfPass` ({len(EXP['stayDegenerateEvenIfPass'])})** — a P on these cells is never written as a fix:"]
    out += [f"- {e}" for e in EXP['stayDegenerateEvenIfPass']]
    out += ['', f"**`degenerateByConstruction` ({len(EXP['degenerateByConstruction'])})**: " + ', '.join(code(c) for c in EXP['degenerateByConstruction']) + '.',
            f"- `degenerateRetirement`: {EXP['degenerateRetirement']}",
            f"- `degenerateRetirementCheck`: script {code(EXP['degenerateRetirementCheck']['script'])}, line ends with "
            f"{code(EXP['degenerateRetirementCheck']['lineEndsWith'])}, units " +
            '; '.join(f"{p} {', '.join(u) or '—'}" for p, u in EXP['degenerateRetirementCheck']['units'].items()) + ', keys ' +
            '; '.join(f"{code(c)} → {code(k)}" for c, k in EXP['degenerateRetirementCheck']['keys'].items()) + '.',
            '', f"**`ringFenced`**: {code(EXP['ringFenced']['test'])} — {EXP['ringFenced']['rule']}",
            '', '**`recordedWall`**: ' + ', '.join(code(c) for c in EXP['recordedWall']) + ' (watched, never a target).']
    return '\n'.join(out)

def r_union():
    out = ['| lane | captures web / ios / android | wire | may-move (android) | named must-not-move | predictions | gating rows | revert units |',
           '|---|---|---|---|---|---|---|---|']
    for lid, l in LANES.items():
        cc = l['captureCarriers']
        mm = len(l.get('mayMove', {}).get('android', [])) if isinstance(l.get('mayMove'), dict) else 0
        out.append(f"| {lid} | {len(cc['web'])} / {len(cc['ios'])} / {len(cc['android'])} | {len(l['wireCarriers'])} | {mm} | "
                   f"{len(l['mustNotMove'])} | {len(l['predictions'])} | {sum(1 for p in l['predictions'] if p['gating'])} | "
                   f"{len(l['revertUnits'])}{' (+ ' + str(len(l['contingencyUnits'])) + ' contingency)' if l.get('contingencyUnits') else ''} |")
    u = EXP['unionCaptureCarriers']; mm = EXP['unionMayMoveCaptures']
    out += ['', f"Union (`expectations.json`): capture carriers web {len(u['web'])} · iOS {len(u['ios'])} · Android {len(u['android'])}; "
            f"wire carriers {len(EXP['unionWireCarriers'])}; may-move captures web {len(mm['web'])} · iOS {len(mm['ios'])} · Android {len(mm['android'])}; "
            f"`mustNotMoveComplement` {EXP['mustNotMoveComplement']['count']} cells — {EXP['mustNotMoveComplement']['rule']}",
            f"- `wireRenumbering.rule`: {EXP['wireRenumbering']['rule']}",
            f"- `wireRenumbering.expectedShadow`: {json.dumps(EXP['wireRenumbering']['expectedShadow'])} — {EXP['wireRenumbering']['noShadowFrom']}"]
    return '\n'.join(out)

# ── per-lane blocks ────────────────────────────────────────────────────────────────────────────────────────────────────
def r_facts(lid):
    l = LANES[lid]; o = l['ownership']; cc = l['captureCarriers']
    out = [f"- **Lane dir** `{l['dir']}/` (note `_note.md`); brief(s): " + ', '.join(code(b) for b in l['briefs']) + '.',
           '- **Owned:**'] + [f"  - {code(p)}" for p in o['owned']]
    out += ['- **Seams** (patches, never direct edits; §3):' + (' none.' if not o['seams'] else '')] + [f"  - {s}" for s in o['seams']]
    out += ['- **Read-only:** ' + '; '.join(code(p) for p in o['readOnly']) + '.']
    rule = l['carrierRule']
    if isinstance(rule, dict):
        out += ['- **Carrier rule** (`carrierRule`):'] + [f"  - {k}: {v}" for k, v in rule.items()]
    else:
        out += [f"- **Carrier rule** (`carrierRule`): {rule}"]
    out += [f"- **Capture carriers** web {len(cc['web'])} · iOS {len(cc['ios'])} · Android {len(cc['android'])}; wire {len(l['wireCarriers'])}; "
            f"named must-not-move {len(l['mustNotMove'])} (`watchlist.txt` block {lid.split('-', 1)[0]}).",
            '- **Revert units** (`revertUnits`; one commit each):']
    for u, v in l['revertUnits'].items():
        caps = ' / '.join(str(len(v['captures'][p])) for p in PLATS)
        extra = ''.join(f" {k}: {v[k]}" for k in v if k not in ('commit', 'captures', 'wire', 'revertOrder'))
        out.append(f"  - **{u}** — revertOrder {code(' → '.join(v['revertOrder']))}; captures web / ios / android {caps}; "
                   f"commit: {v['commit']}.{extra}")
    for u, v in l.get('contingencyUnits', {}).items():
        out.append(f"  - **{u}** (CONTINGENCY, not a unit until it lands) — trigger: {v['trigger']}; commit: {v['commit']}; on land: {v['onLand']}")
    for k in ('pair', 'neverShip', 'dryRuns', 'mayMoveRule', 'landingOrder'):
        if k in l:
            out.append(f"- **`{k}`**: " + (code(' → '.join(l[k])) if isinstance(l[k], list) else l[k]))
    if 'sharedStems' in l:
        out.append(f"- **`sharedStems`** ({len(l['sharedStems'])}, C2): " + '; '.join(f"{code(k)} ({v})" for k, v in l['sharedStems'].items()))
    if 'degenerateRetirement' in l:
        out.append('- **`degenerateRetirement`**: ' + '; '.join(f"{code(k)} ← {', '.join(code(x) for x in v)}" if isinstance(v, list) else f"{k}: {v}"
                                                         for k, v in l['degenerateRetirement'].items()))
    out += [f"- **Stage 1** (`stage1Sections` {', '.join(l['stage1Sections']) or 'none'}; stage 2 adds `probeSections` "
            f"{', '.join(s for s in l['probeSections'] if s not in l['stage1Sections']) or 'nothing'}). `stage1Decision`: {l['stage1Decision']}"]
    return '\n'.join(out)

def r_predictions(lid):
    out = ['| cell | from → to | tier | floor · gating | direction | units | geometry |', '|---|---|---|---|---|---|---|']
    for p in LANES[lid]['predictions']:
        if p.get('floor') is not None:
            fl = f"**{p['floor']}**"
        elif p.get('floorNA'):
            fl = 'floorNA'
        else:
            fl = '—'
        fl += ' · gating' if p['gating'] else ' · not gating'
        extra = ''
        if p.get('fallbackIfReverted'):
            extra = ' — fallbackIfReverted: ' + '; '.join(f"{k}: {v}" for k, v in p['fallbackIfReverted'].items())
        if p.get('predictedDelta') is not None:
            extra += f" — predictedDelta {p['predictedDelta']}"
        if p['kind'] == 'non-corpus':      # an instrument / unscored-capture row: its "cell" is the sentence that says what is read
            out.append(f"| {esc(p['cell'])} | — (not a scored cell) | — | {fl} | — | {esc(', '.join(p.get('units') or []))} | — |")
            continue
        frm = f"{p['from']} → {p['to']}"
        out.append(f"| {code(p['cell'])} | {esc(frm + extra)} | {esc(p['confidence'])} | {fl} | {esc(p.get('direction') or '—')} | "
                   f"{esc(', '.join(p.get('units') or []))} | {esc(p.get('geometry') or '—')} |")
    return '\n'.join(out)

def r_geometry(lid):
    out = []
    for g in LANES[lid]['geometryProbes']:
        exp = g.get('expect') or {}; gat = g.get('gating') or {}; rep = g.get('report') or []
        ctl = [k for k in exp if k not in gat and k not in rep]
        out.append(f"- {code(g['cmd'])} — {len(exp)} keys: gating {len(gat)} · report {len(rep)} · control {len(ctl)}"
                   + (f" · dropped {len(g['dropped'])}" if g.get('dropped') else ''))
        for k, u in gat.items():
            out.append(f"  - GATING {code(k)} → {code(exp[k])} reverts **{u}**" + (f" (contains {code(g['contains'][k])})" if g.get('contains', {}).get(k) else ''))
        if rep:
            out.append('  - report: ' + ', '.join(code(k) for k in rep))
        if ctl:
            out.append('  - control: ' + ', '.join(code(k) for k in ctl))
        for k, why in (g.get('dropped') or {}).items():
            out.append(f"  - DROPPED {code(k)}: {why}")
        for k in ('reasonToUnit',):
            if k in g:
                out.append('  - `reasonToUnit`: ' + '; '.join(f"{code(a)} → {b}" for a, b in g[k].items()))
        for k in ('onWave54Final', 'teeth'):
            if k in g:
                out.append(f"  - `{k}`: {g[k]}")
    return '\n'.join(out)

# ── §6 / §7 / §8 / §9 blocks ───────────────────────────────────────────────────────────────────────────────────────────
def r_record():
    out = [f"- `scoreOfRecord`: {code(EXP['scoreOfRecord'])}",
           f"- `geometryGate.closingCmd`: {code(EXP['geometryGate']['closingCmd'])}",
           f"- `adjudicate`: {code(EXP['adjudicate'])}",
           f"- `scoreReadout`: {code(EXP['scoreReadout'])}",
           f"- `corpusSnapshotSource`: {EXP['corpusSnapshotSource']}",
           f"- `geometryGate.what`: {EXP['geometryGate']['what']}", '',
           '| file (`closingGateFiles`) | written by · read by · never read by |', '|---|---|']
    out += [f"| {code(k)} | {esc(v)} |" for k, v in EXP['closingGateFiles'].items()]
    out += ['', '**`readerChanges`** (the wave-55 copies of the two gate readers):'] + [f"- `{k}`: {v}" for k, v in EXP['readerChanges'].items()]
    out += ['', '**`controlCalibrations`**:'] + [f"- {c['pair']} → **{c['expect']}** ({c['record']})" for c in EXP['controlCalibrations']]
    out += ['', '**`adjudicateCalibrations`**:'] + [f"- {c['input']} → **{c['expect']}** ({c['record']})" for c in EXP['adjudicateCalibrations']]
    return '\n'.join(out)

def r_probes():
    s1, s2 = EXP['stage1Probe'], EXP['probeRun']
    out = [f"**Stage 1 `{s1['runId']}`** ({len(s1['sections'])} sections): {code(s1['cmd'])}",
           f"- `hashRead` (while the devices are up): {code(s1['hashRead'])}" if s1.get('hashRead') else '- `hashRead`: —',
           f"- `readWith`: {s1['readWith']}",
           f"- `decides` ({len(s1['decides'])} units): " + ', '.join(s1['decides']) + '.',
           '- `unitCoverage` (stage-1 carrier captures / carriers first measured at stage 2): ' +
           '; '.join(f"{u} {v['stage1']}" + (f" (stage 2 only: {', '.join(x.replace('wpt__', '') for x in v['stage2Only'])})" if v['stage2Only'] else '')
                     for u, v in s1['unitCoverage'].items()) + '.',
           '- `readOut` (base first everywhere):'] + [f"  - `{k}`: {code(v) if k not in ('order', 'records') else v}" for k, v in s1['readOut'].items()]
    for rid, rp in (s1.get('reprobes') or {}).items():
        out += [f"- **re-probe `{rid}`** (D13): {code(rp['cmd'])} — sections: {rp['sections']}", f"  - `hashRead`: {code(rp['hashRead'])}"] + \
               [f"  - `{k}`: {code(v) if k not in ('order', 'records') else v}" for k, v in rp['readOut'].items() if k != 'order']
    out += ['', f"**Stage 2 `{s2['runId']}`** ({len(s2['sections'])} sections): {code(s2['cmd'])}",
            f"- `hashRead` (while the devices are up): {code(s2['hashRead'])}" if s2.get('hashRead') else '- `hashRead`: —',
            '- `readOut`:'] + [f"  - `{k}`: {code(v) if k not in ('order', 'records') else v}" for k, v in s2['readOut'].items()]
    out += ['- `notProbed`:'] + [f"  - {k}: {v}" for k, v in s2['notProbed'].items()]
    out += ['- `keysFirstReadAtTheGate`: ' + ', '.join(code(k) for k in s2['keysFirstReadAtTheGate']) + '.']
    out += ['', f"**`beforeEveryDeviceRun`**: {code(EXP['beforeEveryDeviceRun'])}"]
    if EXP.get('beforeEveryDeviceRunNote'):      # round 3 (verify M1): the prose is its own field, so the string stays executable
        out += ['', f"- `beforeEveryDeviceRunNote`: {EXP['beforeEveryDeviceRunNote']}"]
    return '\n'.join(out)

def r_revert():
    return '\n'.join(f"- **{r.split(' ', 1)[0]}** {r.split(' ', 1)[1]}" for r in EXP['revertRule'])

def r_arms():
    out = ['| arm | lane | units | against | when | sections | platforms | drops (child first) | expect |', '|---|---|---|---|---|---|---|---|---|']
    for a in EXP['abArms']:
        out.append(f"| {code(a['arm'])} | {a['lane']} | {esc(', '.join(a.get('units', [])))} | {code(a.get('against', 'wave55-final'))} | {esc(a['when'])} | "
                   f"{esc(', '.join(a.get('sections', [])))} | {', '.join(a['platforms'])} | {esc(' → '.join(a.get('drops', [])) or '—')} | "
                   f"{esc(a['expect'])}{esc(' — narrowed: ' + a['narrowedBy']) if a.get('narrowedBy') else ''} |")
    for a in EXP.get('abArmsWithdrawn', []):
        out.append(f"| ~~{code(a['arm'])}~~ | {a['lane']} | {esc(', '.join(a.get('units', [])))} | — | WITHDRAWN: {esc(a['withdrawnBy'])} | | | | |")
    r = EXP['abRead']
    out += ['', f"`abRead`: runId {code(r['runId'])}; runner {r['runner']}; cmd {code(r['cmd'])}; order: {r['order']}"]
    if r.get('armsFile'):
        out += ['', f"`abRead.armsFile`: {r['armsFile']}"]
    return '\n'.join(out)

def r_opening():
    o = EXP['openingGate']
    return '\n'.join([f"- `openingGate.cmd`: {code(o['cmd'])}", f"- `expect`: {o['expect']}"] +
                     [f"- also: {code(a)}" for a in o['alsoRun']] + [f"- `onDivergence`: {o['onDivergence']}"])

def r_landing():
    """§4's unit commit list, rendered from landing-manifest.json (land-units.sh's own ORDER table, generated). A contingency
    unit is a `--` line until expectations.json makes it a revert unit (plan-build.py --contingency), then a numbered one."""
    units = sorted(LANDING['units'], key=lambda u: u['seq'])
    short = {'kt': '.kt', 'swift': '.swift', 'tsx': '.tsx', 'xf': 'extract-fixture'}
    rev = {(lid.split('-', 1)[0], u) for lid, l in LANES.items() for u in l['revertUnits']}
    out = [f"`landing-manifest.json` sha256 `{LANDING_SHA}` ({LANDING['about'].split(';')[0]}); "
           f"{LANDING['counts']['revertUnits']} revert units, optional {', '.join(LANDING['counts']['optional']) or '—'}, "
           f"contingency {', '.join(LANDING['counts']['contingency']) or '—'}.", '', '```landing-order']
    for u in units:
        seams = ' '.join(f"+ {os.path.basename(s['patch'])} ({next((v for k, v in short.items() if LANDING['seamFiles'][k] == s['seamFile']), s['seamFile'])})"
                         for s in u['seams'])
        tag = f"[{u['kind']}]" if u['kind'] != 'unit' else ''
        lead = f"{u['seq']:2d}" if (u['lane'], u['unit']) in rev else '--'
        out.append(f"{lead}  {u['lane']} {u['unit']:<13} {tag:<11} {seams}".rstrip())
    out += ['```', '', f"**`orderConstraints`** ({len(LANDING['orderConstraints'])}, asserted by `land-units.sh` in every mode):"]
    out += [f"- {c['before']} < {c['after']} — {c['why']}" for c in LANDING['orderConstraints']]
    out += ['', '**`deliveryContract`** (what each lane delivers in its lane dir; `land-units.sh --check` refuses the rest):']
    out += [f"- `{k}`: {v if isinstance(v, str) else '; '.join(v)}" for k, v in LANDING['deliveryContract'].items()]
    out += ['', '**`sharedPaths`** (the only paths two lanes may both touch): ' + ', '.join(code(p) for p in LANDING['sharedPaths']) + '.']
    return '\n'.join(out)

def r_decisions():
    out = ['| id | conflict (briefs-audit / generator) | resolution (`expectations.json` `planDecisions`) |', '|---|---|---|']
    out += [f"| {d['id']} | {esc(d['conflict'])} | {esc(d['resolution'])} |" for d in EXP['planDecisions']]
    return '\n'.join(out)

RENDERERS = {'header': r_header, 'plan-build-report': r_report, 'movement': r_movement, 'tally': r_tally,
             'tally-by-lane': r_tally_by_lane, 'stage1-required': r_stage1_required,
             'degenerate': r_degenerate, 'union': r_union, 'record': r_record, 'probes': r_probes, 'revert-rule': r_revert,
             'ab-arms': r_arms, 'opening': r_opening, 'plan-decisions': r_decisions, 'landing-order': r_landing}
for _lid in LANES:
    _s = _lid.split('-', 1)[0]
    RENDERERS[f'{_s}-facts'] = (lambda x: lambda: r_facts(x))(_lid)
    RENDERERS[f'{_s}-predictions'] = (lambda x: lambda: r_predictions(x))(_lid)
    RENDERERS[f'{_s}-geometry'] = (lambda x: lambda: r_geometry(x))(_lid)

BLOCK = re.compile(r'<!-- gen:([\w-]+) \(plan-prose\.py; do not edit by hand\) -->\n(.*?)\n<!-- /gen:\1 -->', re.S)
def start(name): return f'<!-- gen:{name} (plan-prose.py; do not edit by hand) -->'

if RENDER:
    print(RENDERERS[RENDER]()); sys.exit(0)
if MODE is None:
    print(__doc__ or 'usage: plan-prose.py --fill|--check [PLAN.md] (see the header)', file=sys.stderr); sys.exit(2)

text = open(PLAN).read()

if MODE == '--fill':
    seen = []
    def sub(m):
        name = m.group(1)
        if name not in RENDERERS:
            sys.exit(f'plan-prose: unknown block gen:{name} in {PLAN}')
        seen.append(name)
        return f"{start(name)}\n{RENDERERS[name]()}\n<!-- /gen:{name} -->"
    new = BLOCK.sub(sub, text)
    missing = [n for n in RENDERERS if n not in seen]
    dup = sorted({n for n in seen if seen.count(n) > 1})
    if missing or dup:
        sys.exit(f'plan-prose: blocks missing {missing}, duplicated {dup}')
    open(PLAN, 'w').write(new)
    print(f'plan-prose --fill: {len(seen)} blocks rendered from expectations.json sha256 {EXP_SHA[:16]}… into {os.path.relpath(PLAN)}')
    sys.exit(0)

# ── --check ────────────────────────────────────────────────────────────────────────────────────────────────────────────
bad = []
found = [(m.group(1), m.group(2)) for m in BLOCK.finditer(text)]
names = [n for n, _ in found]
for n in RENDERERS:
    if names.count(n) != 1:
        bad.append(f'1. block gen:{n} present {names.count(n)} times (want exactly 1)')
for n, body in found:
    if n not in RENDERERS:
        bad.append(f'1. unknown block gen:{n}')
    elif body != RENDERERS[n]():
        fresh = RENDERERS[n]().split('\n'); old = body.split('\n')
        first = next((i for i in range(max(len(fresh), len(old))) if (fresh[i:i + 1] or [None]) != (old[i:i + 1] or [None])), None)
        bad.append(f'1. block gen:{n} differs from its rendering (first differing line {first}: '
                   f'PLAN {(old[first] if first is not None and first < len(old) else "<none>")[:120]!r} vs fresh '
                   f'{(fresh[first] if first is not None and first < len(fresh) else "<none>")[:120]!r}) — re-run --fill')

hand = BLOCK.sub('', text)                          # the hand-written prose: everything outside the gen blocks
sec9 = hand.split('\n## 9.', 1)[1].split('\n## 10.', 1)[0] if '\n## 9.' in hand else ''
for d in EXP['planDecisions']:
    if not re.search(r'^\| ' + re.escape(d['id']) + r' \|', sec9, re.M):
        bad.append(f"2. §9 has no hand-written row for planDecisions {d['id']}")

CITE = re.compile(r'wave54-final ((?:[\w.()-]+/)+[\w.()-]+?) (web|ios|android) ([Pf]) ([0-9]+(?:\.[0-9]+)?)')
n_cite = 0
for m in CITE.finditer(hand):
    test, plat, verdict, ssim = m.groups()
    key = f'{test}.html {plat}'
    n_cite += 1
    if key not in CELLS['cells']:
        bad.append(f'3. cited cell not scored at wave54-final: {m.group(0)!r}')
    elif CELLS['cells'][key] != f'{verdict} {ssim}':
        bad.append(f"3. cited cell disagrees with cells-wave54-final.json: {m.group(0)!r} vs {CELLS['cells'][key]!r}")

lo = re.search(r'```landing-order\n(.*?)```', text, re.S)      # rendered from landing-manifest.json (gen:landing-order)
if not lo:
    bad.append('4. no ```landing-order``` block in §4')
    order = []
else:
    order = []
    for line in lo.group(1).splitlines():
        m = re.match(r'\s*(\d+)\s+(L\d) (\S+)', line)
        if m:
            order.append((SHORT[m.group(2)], m.group(3)))
want = [(lid, u) for lid, l in LANES.items() for u in l['revertUnits']]
for x in want:
    if order.count(x) != 1:
        bad.append(f'4. landing-order lists {x[0]} {x[1]} {order.count(x)} times (want exactly 1)')
for x in order:
    if x not in want:
        bad.append(f'4. landing-order lists {x[0]} {x[1]}, which is not a revert unit of expectations.json')
pos = {x: i for i, x in enumerate(order)}
def before(a, b, why):
    if a in pos and b in pos and not pos[a] < pos[b]:
        bad.append(f'4. {a[0].split("-")[0]} {a[1]} must land before {b[0].split("-")[0]} {b[1]} ({why})')
for lid, l in LANES.items():
    for u, v in l['revertUnits'].items():
        ro = v['revertOrder']
        for dep in ro[:ro.index(u)] if u in ro else []:
            before((lid, u), (lid, dep), f'revertOrder of {u} is {ro}: {dep} is reverted first, so it lands after')
    lo_ = l.get('landingOrder') or []
    for a, b in zip(lo_, lo_[1:]):
        before((lid, a), (lid, b), f'{lid} landingOrder')
for a in [x for x in order if x[0] == SHORT['L4']]:
    for b in [x for x in order if x[0] == SHORT['L3']]:
        before(a, b, 'C10: SeamReachabilityTest lines land L4 → L3 → L5')
for a in [x for x in order if x[0] == SHORT['L3']]:
    for b in [x for x in order if x[0] == SHORT['L5']]:
        before(a, b, 'C10: SeamReachabilityTest lines land L4 → L3 → L5')
before((SHORT['L1'], 'NB-ios'), (SHORT['L5'], 'U3-ios'), "seam 6 is re-anchored by content after L1's seam 1")
before((SHORT['L5'], 'U2o-ios'), (SHORT['L5'], 'D'), 'C7: the SUFFIX NOTE lands after U2o')
before((SHORT['L5'], 'U2o-android'), (SHORT['L5'], 'D'), 'C7: the SUFFIX NOTE lands after U2o')

for lid in LANES:
    s, name = lid.split('-', 1)
    if not re.search(rf'^### {s} · {re.escape(name)}\b', hand, re.M):
        bad.append(f'5. no "### {s} · {name}" heading')

# 7. (round 1, S7) a regenerable count typed by hand outside the gen blocks — it drifts on the next regeneration unseen.
STRAY = [r'\b\d+ revert units\b', r'\b\d+ of the \d+\b', r'\ball \d+ (?:gating )?keys\b', r'\bproves that all \d+\b', r'\b\d+ registered patches\b',
         r'\b\d+ list entries\b', r'^\s*- L\d: \d+ —', r'\[(?:M|X|F|S|W|C|I|K|PO)\] ×\d+', r'\bthe \d+ gating (?:keys|rows|flip rows|predictions)\b',
         r'\bthe \d+ controls\b', r'\b\d+ in full\b', r'\b\d+ withdrawn\b', r'\bmay-move (?:android )?\d+\b', r'\b\d+ may-move (?:stems|captures)\b']
for pat in STRAY:
    for m in re.finditer(pat, hand, re.M):
        line = hand[hand.rfind('\n', 0, m.start()) + 1:hand.find('\n', m.end())]
        bad.append(f'7. a regenerable count typed by hand outside the gen blocks: {m.group(0)!r} in {line.strip()[:110]!r} — render it, or cite the generated file')

# 6. land-units.sh's manifest and plan-build.py's JSON describe the same units with the same revert orders (two generators
#    written by two stages: neither may drift from the other unseen).
for u in LANDING['units']:
    lid = SHORT.get(u['lane'])
    ru = LANES.get(lid, {}).get('revertUnits', {}).get(u['unit']) if lid else None
    cu = LANES.get(lid, {}).get('contingencyUnits', {}).get(u['unit']) if lid else None
    if ru is None and cu is None:
        bad.append(f"6. landing-manifest unit {u['lane']} {u['unit']} is neither a revert unit nor a contingency unit of expectations.json")
    elif ru is not None and ru['revertOrder'] != u['revertOrder']:
        bad.append(f"6. {u['lane']} {u['unit']}: revertOrder {u['revertOrder']} in landing-manifest.json vs {ru['revertOrder']} in expectations.json")
    elif ru is None and u['kind'] != 'contingency':
        bad.append(f"6. {u['lane']} {u['unit']} is a contingency in expectations.json but kind {u['kind']!r} in landing-manifest.json")

print(f'plan-prose --check {os.path.relpath(PLAN)} against expectations.json sha256 {EXP_SHA[:16]}…: '
      f'{len(found)} gen blocks · {len(EXP["planDecisions"])} decision ids · {n_cite} wave54-final cell citations · '
      f'{len(order)} landing-order units (want {len(want)})')
for b in bad:
    print('  RED  ' + b)
print('plan-prose --check: ' + ('HOLDS' if not bad else f'FAILS — {len(bad)} violation(s)'))
sys.exit(1 if bad else 0)
